282	     * floor (a correction has none), rounded as the sheet's policy date decides for it; null (n/a) with none.
283	     */
284	    public BigDecimal liveDue(String sheetId, Person person, Claim claim) {
285	        Sheet sheet = sheets.load(sheetId);
286	        BigDecimal floor = claim.isCorrection() ? null : sheet.getFloor();
287	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
288	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
289	                .map(pct -> floored(dueOn(claim.getAmount(), pct, rounding), floor)).orElse(null);
290	    }
