305	     * correction gains none.
306	     */
307	    public BigDecimal due(String sheetId, Person person, Claim claim) {
308	        BigDecimal figure = figure(sheetId, person, claim);
309	        return claim.getStatus().isOpen() && !claim.isCorrection()
310	                ? withLateCharge(figure, claim, sheets.load(sheetId))
311	                : figure;
312	    }
313	
314	    /**
315	     * The figure (null for n/a) of the claim, with the sheet's late percent of it added for every full 30 days it is
316	     * overdue (past its due-by) by the sheet's today, rounded like its due. The charge is never bound by a statement: it keeps
317	     * following the sheet's today and its policy date.
318	     */
319	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Sheet sheet) {
320	        if (figure == null || sheet == null || sheet.getToday() == null) {
321	            return figure;
322	        }
323	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday());
324	        long periods = overdue > 0 ? overdue / 30 : 0;
325	        if (periods == 0 || sheet.getLatePct().signum() == 0) {
326	            return figure;
327	        }
328	        return figure.add(dueOn(figure, sheet.getLatePct().multiply(BigDecimal.valueOf(periods)),
329	                sheet.roundingOn(claim.getRoundsOn())));
330	    }
