333	     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
334	     * the transaction ends, so a period closing at the same moment is checked in turn.
335	     */
336	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
337	        sheets.lock(sheetId);
338	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
339	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
340	        }
341	    }
342	
