344	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
345	     * claim of the person, else refused; null for any other claim.
346	     */
347	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
348	        if (amount.signum() >= 0) {
349	            return null;
350	        }
351	        corrects = corrects == null ? null : corrects.strip();
352	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
353	                ClaimStatus.SETTLED)) {
354	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
355	                    "A negative amount must correct a settled claim of the person, named by its number.");
356	        }
357	        return corrects;
358	    }
