361	    private static void refuseAfterRetirement(Person person, LocalDate date) {
362	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
363	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
364	                    "That claim is dated after the person's retirement.");
365	        }
