374	    private static String record(String event, String by, Person person, Claim c) {
375	        String number = c.getNumber();
376	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
377	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
378	                + (number != null ? " number=" + number : "");
379	    }
380	
381	    /**
382	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
383	     * negative amount rounds like its positive).
384	     */
385	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
386	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
387	    }
388	
389	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
390	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
391	        return corrects == null ? on
392	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
393	    }
